/**
 * Service worker registration and the update signal.
 *
 * `virtual:pwa-register` is generated by vite-plugin-pwa at build time, so this module only resolves
 * once the plugin is installed and configured.
 *
 * The app does NOT reload itself when a new version arrives. A student may be halfway through
 * recording a time out, and a reload under their thumb is the kind of surprise that makes people
 * stop trusting an app. Instead the new version is downloaded and waits, a quiet notice offers to
 * apply it, and it takes effect by itself the next time the app is fully closed and reopened —
 * which, for a home-screen app, is most of the time.
 */
import { registerSW } from 'virtual:pwa-register';

let state = { needRefresh: false, offlineReady: false };
let apply = null;
const subs = new Set();
const notify = () => subs.forEach((fn) => fn(state));

export function subscribeSw(fn) {
  subs.add(fn);
  fn(state);
  return () => subs.delete(fn);
}

export function applyUpdate() {
  if (apply) apply(true);
}

export function initServiceWorker() {
  if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;
  try {
    apply = registerSW({
      immediate: true,
      onNeedRefresh() { state = { ...state, needRefresh: true }; notify(); },
      onOfflineReady() { state = { ...state, offlineReady: true }; notify(); },
      onRegisteredSW(url, reg) {
        // Look for a new version each hour while the app is open, and whenever it is brought back
        // to the front. Without this an installed app can sit on an old build for days.
        if (!reg) return;
        const check = () => { if (navigator.onLine) reg.update().catch(() => {}); };
        setInterval(check, 60 * 60 * 1000);
        document.addEventListener('visibilitychange', () => { if (!document.hidden) check(); });
      },
      onRegisterError(err) { console.error('Service worker did not register:', err); }
    });
  } catch (err) {
    console.error('Service worker registration threw:', err);
  }
}
